def f(g):
    # separator color: value forming full horizontal lines
    vals=set(x for r in g for x in r)
    sep=None
    for v in vals:
        if any(all(x==v for x in r) for r in g): sep=v
    rs=[i for i in range(len(g)) if all(x==sep for x in g[i])]
    cs=[c for c in range(len(g[0])) if all(g[r][c]==sep for r in range(len(g)))]
    def rev(a): return [[a[r][c] for c in range(len(a[0])-1,-1,-1)] for r in range(len(a)-1,-1,-1)]
    # find source cell: nonzero non-sep pixels
    src=None
    for rr in range(len(rs)-1):
        for cc in range(len(cs)-1):
            r0,r1=rs[rr]+1,rs[rr+1]; c0,c1=cs[cc]+1,cs[cc+1]
            if any(g[r][c] not in (0,sep) for r in range(r0,min(r1,len(g))) for c in range(c0,min(c1,len(g[0])))):
                src=(rr,cc)
    out=[r[:] for r in g]
    if src:
        rr,cc=src
        r0,r1=rs[rr]+1,rs[rr+1]; c0,c1=cs[cc]+1,cs[cc+1]
        Hg,Wg=r1-r0,c1-c0
        # opposite cell
        op=lambda x: len(rs)-1-rr if True else None
        otr, otc = len(rs)-1-rr, len(cs)-1-cc
        ot0,ot1=rs[otr]+1,rs[otr+1]; oco,oco1=cs[otc]+1,cs[otc+1]
        sub=[[g[r][c] for c in range(c0,c1)] for r in range(r0,r1)]
        out2=[rev(row) for row in sub]
        for dr in range(Hg):
            for dc in range(Wg):
                out2[dr][dc]=g[r0+Hg-1-dr][c0+Wg-1-dc]
        for dr in range(len(out2)):
            for dc in range(len(out2[0])):
                if out2[dr][dc]:
                    out[ot0+dr][oco1+dc]=out2[dr][dc]
    return out
